Insert into CTATTRIBUTE_TYPE (ATTRIBUTE_TYPE,COLLECTION_CDE,DESCRIPTION) values ('supracilliaries','Herp','scale count of the specialized head scales located immediately above the eyes and below the supraocular scales');
Insert into CTATTRIBUTE_TYPE (ATTRIBUTE_TYPE,COLLECTION_CDE,DESCRIPTION) values ('supralabials','Herp','scales that border the mouth opening along the upper jaw, usually of a snake or lizard. If two numbers listed and separated by a dash, comma, or vertical line, the first represents the number of scales on the left and the second number is the scale count for the right side. If one number is listed, this likely means both sides have the same number of scales');
Insert into CTATTRIBUTE_TYPE (ATTRIBUTE_TYPE,COLLECTION_CDE,DESCRIPTION) values ('tail height','Herp','measurement of (usually) tallest point of an animal''s  tail');
