Insert into CTATTRIBUTE_TYPE (ATTRIBUTE_TYPE,COLLECTION_CDE,DESCRIPTION) values ('tail width','Herp','measurement of (usually) the widest point of an animal''s tail');
Insert into CTATTRIBUTE_TYPE (ATTRIBUTE_TYPE,COLLECTION_CDE,DESCRIPTION) values ('tarsus length','Herp','measurement of the ankle region of the hind leg, particularly in frogs, located between the ankle bone (where tibia/fibula meets start of foot/heel) and the start of the foot pad');
Insert into CTATTRIBUTE_TYPE (ATTRIBUTE_TYPE,COLLECTION_CDE,DESCRIPTION) values ('temperature experiment','Cryo',null);
Insert into CTATTRIBUTE_TYPE (ATTRIBUTE_TYPE,COLLECTION_CDE,DESCRIPTION) values ('temperature experiment','IZ',null);
Insert into CTATTRIBUTE_TYPE (ATTRIBUTE_TYPE,COLLECTION_CDE,DESCRIPTION) values ('temporals','Herp','the number of temporal scales located on upper-side of the head, typically between the parietal and supralabial scales and behind the postocular scales. If multiple numbers are given, they indicate the number of anterior v. posterior temporals. If these strongs are separated by a dash or a slash, this indicates the scale counts from the left (first number) v. right (second number) side of the head. If only one string of numbers is provided, this indicates the number of scales of the left and right side of the head are the same.');
